 acceptance={'schema':'experiment_f_f0_acceptance_gates','version':1,'pretraining_lock':True,'basis':'E6/E7 RF-v3 PortScan recall 0.999334/0.998336; E13 RF-v3 DDoS-like 2/801 and 4/1612; E14 requires class-level—not accuracy-only—decision.','mandatory_metrics':['per-class recall','per-class F1','confusion matrix','macro F1','false-positive rates','calibrated/appropriate probability diagnostics','paired predictions against RF-v2 and RF-v3'], 'training_success':{'purpose':'diagnostic only; cannot establish promotion','requirements':['78-feature/provenance/leakage gates pass','training metrics reported without final data','no threshold tuning or final-data access']},'validation_success':{'normal_recall':'>= 0.98 and no more than 0.02 below RF-v3 on identical validation flows','portscan_recall':'>= 0.995 and no more than 0.005 below RF-v3','ddos_recall':'on new ground-truth F DDoS validation sessions, >= 0.20 and >= 0.10 absolute improvement over RF-v3','normal_and_portscan_f1':'each >= 0.98 of RF-v3 value on identical flows','ddos_f1':'>= RF-v3 + 0.10 absolute on new F DDoS validation flows','macro_f1':'>= RF-v3 - 0.02, with no mandatory class gate waived','false_positives':'No >0.02 absolute increase in Normal->DDoS or Normal->PortScan rate versus RF-v3','paired_transitions':'Report RF-v3 PortScan->RF-v4 Normal, RF-v3 Normal->RF-v4 anomaly, RF-v2 DDoS->RF-v4 Normal, RF-v3 Normal->RF-v4 DDoS, RF-v3 DDoS->RF-v4 Normal'},'final_scientific_success':{'replication':'All validation gates reproduced on at least 3 independent sealed sessions per class; aggregate and per-session results shown.','integrity':'Final session/hash/lineage seal remains intact until candidate is frozen; no flow/capture overlap.','comparators':'RF-v2, RF-v3, RF-v4 evaluated on exact same final matrices.'},'promotion_eligibility':'Only after all validation and final scientific gates pass, a separately authorized F10 decision may consider promotion. Passing accuracy alone, training success, or one session never suffices.','failure':'Any mandatory failure is NOT_PROMOTION_ELIGIBLE; document rather than tune or alter thresholds post hoc.'}
 design={'schema':'experiment_f_f0_ground_truth_design','version':1,'topology':topology,'ddos_labeling':labels,'profiles':{'Normal':'Representative bounded benign HTTP, explicitly logged, no concurrent DDoS/PortScan in its window.','PortScan':'Representative approved runtime PortScan profile preserving the evidence class that remediated RF-v2; bounded, controlled, separately labeled.','DDoS':'New bounded distributed HTTP workload from the four independent generators only; F0 supplies no execution commands.'},'split_plan':{'minimum_sessions_per_class_per_split':3,'why':'Three independent smaller sessions per class/split provide minimal replication and permit per-session reporting; one large capture is insufficient.','splits':['F-ADAPTATION','F-VALIDATION','F-FINAL'],'separation':'No session, PCAP hash, raw CSV hash, lineage ID, capture relative, or duplicate flow identity may cross splits. Final remains sealed/unseen until candidate freeze.'},'dataset_composition':{'Normal_allowed':['eligible historical adaptation Normal','new F-ADAPTATION Normal only'],'DDoS_allowed':['frozen historical DDoS adaptation/training evidence','new fully eligible F-ADAPTATION ground-truth DDoS only'],'PortScan_allowed':['eligible historical PortScan','validated Experiment E runtime PortScan adaptation evidence','optional new F-ADAPTATION PortScan only if preregistered'],'forbidden':['Experiment D sealed final-test','all F-VALIDATION and F-FINAL material','E10/E13 automatically relabeled DDoS profiles','duplicate flows','capture/session relatives across splits','unverified or missing-provenance material']},'evidence_per_capture':['PCAP/hash','84-column raw CSV/hash','exact ordered 78 matrix/hash','adapter/crosswalk and extractor identities','model identity when inference occurs','capture interface/source/target/session/split/label/timestamps/profile','generator logs and counts; target evidence where available','predictions/probabilities/alerts/DB exports where applicable','immutable lineage manifest'],'deviations':{'PASS':'All required evidence and gates pass.','PASS_WITH_DOCUMENTED_LIMITATION':'Non-label-affecting limitation, preregistered and accepted before analysis; never used to waive split, identity, checksum, or ground-truth rules.','INVALID':'Evidence/label/integrity/split/source mismatch, empty/partial capture, extractor/checksum/row-count failure; exclude from scientific dataset and preserve record.','ABORTED':'Safety, routing, target, or generator failure; stop workload, preserve evidence, no label/dataset use.','no_silent_correction':True}}
 prereg={'schema':'experiment_f_f0_preregistration','version':1,'generated_at_utc':datetime.now(timezone.utc).isoformat(),'phase':'DESIGN_PREREGISTRATION_ONLY','gate':'PASS','objective':'Future RF-v4 research may improve three-class runtime generalization while preserving PortScan remediation and preventing material Normal/DDoS regression.','frozen_contract':{'classifier_family':'Random Forest','classes':['Normal','DDoS','PortScan'],'feature_count':78,'feature_order_sha256':meta['feature_order_sha256'],'extractor':'CICFlowMeter V3 approved provenance','random_state':42,'no_threshold_hacks_or_feature_changes':True,'no_silent_imputation':True,'session_capture_split':True,'Experiment_D_final_test_permanently_excluded':True,'baselines_frozen':['RF-v2','RF-v3'],'initial_training_policy':{'same_RF_settings_as_RF_v3':meta['rf_parameters'],'justification':'Data-remediation effect must be tested before hyperparameter tuning; any tuning requires a separate preregistration.'}},'topology':topology,'ground_truth_design_file':'reports/experiment_f/preregistration/f0_ground_truth_design.json','acceptance_gates_file':'reports/experiment_f/preregistration/f0_acceptance_gates.json','phase_sequence':['F0 preregistration and ground-truth design','F1 topology/preflight','F2 ground-truth collection','F3 extraction/provenance validation','F4 dataset construction/leakage audit','F5 RF-v4 candidate training','F6 validation evaluation','F7 unseen runtime validation','F8 sealed final evaluation','F9 comparison/scientific decision','F10 separate promotion decision'],'safety':['F0 generates zero traffic','isolated private controlled lab target only','bounded/reproducible/non-destructive future workloads','no public/corporate/uncontrolled target'],'integrity_before':before,'prohibited_in_F0':['traffic or load commands','training/RF-v4 artifact','hyperparameter/threshold change','model activation/promotion','runtime DB writes','historical D/E modification']}
 wr(ROOT/'config/experiment_f.yaml',"""experiment_code: EXPERIMENT_F0\ntitle: RF-v4 Preregistration and Ground-Truth DDoS Design\nphase: DESIGN_PREREGISTRATION_ONLY\nstatus: NOT_AUTHORIZED_TO_EXECUTE\ntraffic_execution_authorized: false\ntraining_authorized: false\ndatabase_writes_authorized: false\nclasses: [Normal, DDoS, PortScan]\nfeature_contract: {count: 78, order_sha256: 9338f50fc3e7efc78d678cc65ab38d428a7f6912ed9467a2b99a449a7c8e3c13}\nextractor: {identity: CICFLOWMETER_V3_CICIDS2017_MODEL_ADAPTER, version: 1.0.0}\nrandom_state: 42\nminimum_sessions_per_class_per_split: 3\nnext_authorized_phase: F1_TOPOLOGY_PREFLIGHT_ONLY\n""")
